window.ScripturaLexicons.BDAG_PART_0124 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enp-bdag\" data-source=\"BDAG\" data-search=\"ἐνπ- enp- forma remissiva ver ἐμπ- BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνπ-</td><td>forma remissiva</td><td>ver ἐμπ-</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enskiroo-bdag\" data-source=\"BDAG\" data-search=\"ἐνσκιρόω enskiróō verbo endurecer; tornar insensível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνσκιρόω</td><td>verbo</td><td>endurecer; tornar insensível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ensternizomai-bdag\" data-source=\"BDAG\" data-search=\"ἐνστερνίζομαι ensternízomai verbo; voz média guardar no íntimo de si mesmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνστερνίζομαι</td><td>verbo; voz média</td><td>guardar no íntimo de si mesmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entalma-bdag\" data-source=\"BDAG\" data-search=\"ἔνταλμα, ατος, τό éntalma substantivo neutro mandamento; preceito obrigatório BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνταλμα, ατος, τό</td><td>substantivo neutro</td><td>mandamento; preceito obrigatório</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entasso-bdag\" data-source=\"BDAG\" data-search=\"ἐντάσσω entássō verbo transitivo inscrever em registro oficial; alistar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντάσσω</td><td>verbo transitivo</td><td>inscrever em registro oficial; alistar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entautha-bdag\" data-source=\"BDAG\" data-search=\"ἐνταῦθα entaûtha advérbio de lugar aqui BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνταῦθα</td><td>advérbio de lugar</td><td>aqui</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entaphiazo-bdag\" data-source=\"BDAG\" data-search=\"ἐνταφιάζω entaphiázō verbo preparar para o sepultamento; sepultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνταφιάζω</td><td>verbo</td><td>preparar para o sepultamento; sepultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entaphiasmos-bdag\" data-source=\"BDAG\" data-search=\"ἐνταφιασμός, οῦ, ὁ entaphiasmós substantivo masculino preparação para o sepultamento; sepultamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνταφιασμός, οῦ, ὁ</td><td>substantivo masculino</td><td>preparação para o sepultamento; sepultamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entello-bdag\" data-source=\"BDAG\" data-search=\"ἐντέλλω entéllō verbo; em nossa literatura, depoente médio ordenar; dar instruções; prescrever BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντέλλω</td><td>verbo; em nossa literatura, depoente médio</td><td>ordenar; dar instruções; prescrever</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enteron-bdag\" data-source=\"BDAG\" data-search=\"ἔντερον, ου, τό énteron substantivo neutro intestino; entranhas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔντερον, ου, τό</td><td>substantivo neutro</td><td>intestino; entranhas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enteuthen-bdag\" data-source=\"BDAG\" data-search=\"ἐντεῦθεν enteûthen advérbio daqui; daqui por diante; disso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντεῦθεν</td><td>advérbio</td><td>daqui; daqui por diante; disso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enteuxis-bdag\" data-source=\"BDAG\" data-search=\"ἔντευξις, εως, ἡ énteuxis substantivo feminino petição; súplica; oração; intercessão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔντευξις, εως, ἡ</td><td>substantivo feminino</td><td>petição; súplica; oração; intercessão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entithemi-bdag\" data-source=\"BDAG\" data-search=\"ἐντίθημι entíthēmi verbo pôr dentro; implantar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντίθημι</td><td>verbo</td><td>pôr dentro; implantar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entimos-bdag\" data-source=\"BDAG\" data-search=\"ἔντιμος, ον éntimos adjetivo honrado; respeitado; precioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔντιμος, ον</td><td>adjetivo</td><td>honrado; respeitado; precioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entole-bdag\" data-source=\"BDAG\" data-search=\"ἐντολή, ῆς, ἡ entolḗ substantivo feminino ordem; mandamento; preceito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντολή, ῆς, ἡ</td><td>substantivo feminino</td><td>ordem; mandamento; preceito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entopios-bdag\" data-source=\"BDAG\" data-search=\"ἐντόπιος, ία, ιον entópios adjetivo; substantivado no plural local; habitantes do lugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντόπιος, ία, ιον</td><td>adjetivo; substantivado no plural</td><td>local; habitantes do lugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entos-bdag\" data-source=\"BDAG\" data-search=\"ἐντός entós advérbio de lugar; preposição com genitivo dentro de; no interior de; entre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντός</td><td>advérbio de lugar; preposição com genitivo</td><td>dentro de; no interior de; entre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entrepo-bdag\" data-source=\"BDAG\" data-search=\"ἐντρέπω entrépō verbo; usos ativos e passivos envergonhar; respeitar; mostrar deferência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντρέπω</td><td>verbo; usos ativos e passivos</td><td>envergonhar; respeitar; mostrar deferência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entrepho-bdag\" data-source=\"BDAG\" data-search=\"ἐντρέφω entréphō verbo; particípio médio-passivo criar; educar; formar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐντρέφω</td><td>verbo; particípio médio-passivo</td><td>criar; educar; formar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-entromos-bdag\" data-source=\"BDAG\" data-search=\"ἔντρομος, ον éntromos adjetivo trêmulo; tremendo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔντρομος, ον</td><td>adjetivo</td><td>trêmulo; tremendo</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-enp-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνπ-</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enp-⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <strong><span class=\"greek\">ἐμπ</span>-</strong>.</p></section></article>\n<article id=\"entry-enskiroo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνσκιρόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enskiróō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Particípio perfeito passivo: <span class=\"greek\">ἐνεσκιρωμένος</span> (cf. <span class=\"greek\">σκιρόομαι</span>, «tornar-se duro»; Xenofonte, De Re Equ. 4, 2; Estoicos III, p. 102, 38; Is 27:1, Teodocião; Etym. Mag., p. 344, 30).</p><p class=\"entry-text\">O sentido primário é «fazer com que se torne duro»; em nossa literatura, usa-se a respeito da insensibilidade moral: <strong>endurecer, tornar insensível</strong>, Hv 3, 9, 8. — DELG, s.v. <span class=\"greek\">σκῖρος</span>.</p></section></article>\n<article id=\"entry-ensternizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστερνίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ensternízomai⟧</span><span class=\"separator\">·</span><span>verbo; voz média</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Particípio perfeito médio: <span class=\"greek\">ἐνεστερνισμένος</span> (vocábulo tardio, encontrado somente em escritores cristãos, geralmente na voz média; Hesíquio; Suda; Pselo, p. 72, 17; B-D-F, § 123, 2).</p><p class=\"entry-text\"><strong>Guardar no íntimo de si mesmo:</strong> <span class=\"greek\">ἐπιμελῶς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἦτε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σπλάγχνοις</span> (subentenda-se <span class=\"greek\">τ</span>. <span class=\"greek\">λόγους</span>), «havíeis guardado cuidadosamente as palavras nas profundezas de vosso ser», 1 Cl 2:1. — DELG, s.v. <span class=\"greek\">στέρνον</span>.</p></section></article>\n<article id=\"entry-entalma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνταλμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éntalma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐντέλλω</span>. Atestado na LXX; PLond IV, 1384, 55 [século VIII d.C.]; Justino, D. 46, 5; 67, 10.</p><p class=\"entry-text\"><strong>Aquilo que é ordenado com força oficial obrigatória: mandamento.</strong> Em associação com <span class=\"greek\">διδασκαλία</span>: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνθρώπων</span>, «mandamentos de homens», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:22</a> (as três passagens remetem a Is 29:13); <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐ</span>., «os mandamentos do Senhor», 2 Cl 17:3. — DELG, s.v. <span class=\"greek\">τέλλω</span>.</p></section></article>\n<article id=\"entry-entasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντάσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entássō⟧</span><span class=\"separator\">·</span><span>verbo transitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo: <span class=\"greek\">ἐνέταξα</span>; perfeito passivo, terceira pessoa do singular: <span class=\"greek\">ἐντέτακται</span>, Jó 15:22, códice A; particípio: <span class=\"greek\">ἐντεταγμένος</span>. Ver <span class=\"greek\">τάσσω</span>; Xenofonte, An. 3, 3, 18 (variante textual); inscrições, papiros, LXX; Josefo, C. Ap. 1, 172.</p><p class=\"entry-text\"><strong>Fazer que alguém seja incluído em registro oficial: inscrever, alistar.</strong> Construído com <span class=\"greek\">εἰς</span> <span class=\"greek\">τι</span>, «em algo»: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀριθμὸν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σῳζομένων</span>, «no número dos que são salvos», 1 Cl 58:2. — DELG, s.v. <span class=\"greek\">τάσσω</span>.</p></section></article>\n<article id=\"entry-entautha-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταῦθα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entaûtha⟧</span><span class=\"separator\">·</span><span>advérbio de lugar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio (desde Homero). <strong>Referente a uma posição relativamente próxima de quem fala: aqui.</strong> Ox 840, 23. — DELG, s.v. <span class=\"greek\">ἔνθα</span>.</p></section></article>\n<article id=\"entry-entaphiazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταφιάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entaphiázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa do singular: <span class=\"greek\">ἐνταφιάσει</span> (TestJud 26:3). Ver a entrada seguinte e <span class=\"greek\">τάφος</span>; Anth. Pal. 11, 125, 5; Plutarco, Mor. 995c; SIG 1235, 5 [século I d.C.]; Gn 50:2; AssMos Fgm. g; TestJud 26:3.</p><p class=\"entry-text\"><strong>Preparar para o sepultamento; sepultar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:40</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐνταφιάσαι</span> <span class=\"greek\">με</span>, «para me preparar para o sepultamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:12</a>. — DELG, s.v. <span class=\"greek\">θάπτω</span>; M-M.</p></section></article>\n<article id=\"entry-entaphiasmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταφιασμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entaphiasmós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver a entrada precedente; escólios a Eurípides, Phoen. 1654, e a Aristófanes, Plut. 1009. A forma <span class=\"greek\">ἐνταφιαστής</span> é atestada já em PParis 7, 6 [100 a.C.]; Gn 50:2.</p><p class=\"entry-text\"><strong>Realização dos procedimentos habituais de um sepultamento: preparação para o sepultamento ou o próprio sepultamento</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:7</a>. — Field, Notes, p. 98; DELG, s.v. <span class=\"greek\">θάπτω</span>; M-M.</p></section></article>\n<article id=\"entry-entello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entéllō⟧</span><span class=\"separator\">·</span><span>verbo; em nossa literatura, depoente médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἔνταλμα</span>. Atestado em Píndaro e outros; porém, normalmente, e exclusivamente em nossa literatura, como <strong>depoente médio</strong> (frequente desde Heródoto; inscrições, papiros, LXX, pseudoepígrafos, Josefo, Justino; Melitão, P. 11, 73). Futuro <span class=\"greek\">ἐντελοῦμαι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:10</a>); primeiro aoristo <span class=\"greek\">ἐνετειλάμην</span>; perfeito <span class=\"greek\">ἐντέταλμαι</span> (em nossa literatura, apenas com sentido ativo, como em Políbio 17, 2, 1; Herodiano 1, 9, 9; Tb 5:1; 2Mc 11:20; Josefo, Vi. 318 [mais-que-perfeito]); segunda pessoa do singular <span class=\"greek\">ἐντέταλσαι</span>, Hm 12, 6, 4; terceira pessoa do singular do mais-que-perfeito <span class=\"greek\">ἐνετέταλτο</span> (Justino); primeira forma de aoristo passivo, terceira pessoa do singular do subjuntivo <span class=\"greek\">ἐνταλθῇ</span> (TestJob 20:9).</p><p class=\"entry-text\"><strong>Dar ou deixar instruções; ordenar, mandar, dar ordens.</strong> Uso absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:4</a>, variante textual (seguido de <span class=\"greek\">λέγων</span>); Pol 6:3; B 7:3. Com dativo <span class=\"greek\">τινί</span>, «a alguém»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:2</a>; 13:47. Com acusativo <span class=\"greek\">τί</span>, «algo» (Herodiano 1, 9, 10; Sir 48:22): IRo 3:1; Hm 12, 6, 4. Com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «ordenar algo a alguém» (Heródoto 1, 47; Diógenes de Enoanda [século II d.C.], Fgm. 50, 3 [= 66 William], acerca de instruções testamentárias: <span class=\"greek\">φίλοις</span> <span class=\"greek\">τάδε</span> <span class=\"greek\">ἐντέλλομαι</span>; Josefo, Vi. 242): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:14</a>. Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «a respeito de algo» (1Mc 9:55): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a>.</p><p class=\"entry-text\">Com <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «a alguém sobre algo» (UPZ 61, 9 [161 a.C.]; APF 8, p. 212, n.º 14, 12; BGU 1755, 14 [século I a.C.]; Sir 17:14; 1Mc 3:34; Josefo, Ant. 7, 358): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:10</a> (ambas citam Sl 90:11). Seguido de infinitivo (Gn 42:25; 2Cr 36:23; Manetão, 609 Fgm. 9a, 98 Jac. [em Josefo, C. Ap. 1, 98]; Justino, D. 22, 11, entre outros): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:5</a>; Hv 5:7; Hm 4, 1, 1. Com acusativo e infinitivo: <span class=\"greek\">ἐντέταλται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰσραὴλ</span> <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">δάμαλιν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἄνδρας</span>, «foi ordenado a Israel que os homens oferecessem uma novilha», B 8:1. Seguido do genitivo do infinitivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:10</a> (Sl 90:11). Seguido de <span class=\"greek\">ὅτι</span>: «dizer enfaticamente», IRo 4:1. Seguido de <span class=\"greek\">ἵνα</span> (Josefo, Ant. 8, 375; 7, 356): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:17</a>.</p><p class=\"entry-text\"><span class=\"greek\">τ</span>. <span class=\"greek\">διαθήκης</span> <span class=\"greek\">ἧς</span> (por atração em lugar de <span class=\"greek\">ἥν</span>) <span class=\"greek\">ἐνετείλατο</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, «do decreto que Deus ordenou para vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:20</a>. — DELG, s.v. <span class=\"greek\">τέλλω</span>; M-M, s.v. <span class=\"greek\">ἐντέλλομαι</span>; TW.</p></section></article>\n<article id=\"entry-enteron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντερον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énteron⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Desde Homero e outros; predominantemente no plural, também em Artemidoro 1, 33, p. 35, 15 [que distingue <span class=\"greek\">ἔντερα</span> de <span class=\"greek\">σπλάγχνα</span>]; PGM 4, 2596; 2658; Gn 43:30; 2Mc 14:46. Primeiramente «intestino(s)» e também <strong>entranhas</strong> (no singular, Hipócrates, <span class=\"greek\">π</span>. <span class=\"greek\">νους</span>. 3, 14, vol. VII, p. 134; Diocles 43, p. 136, 33; Sir 31:20).</p><p class=\"entry-text\"><span class=\"greek\">φαγεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄπλυτον</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὄξους</span>, «comer as entranhas sem lavá-las, com vinagre», B 7:4 (citação de origem incerta). — DELG, s.v. <span class=\"greek\">ἐν</span>.</p></section></article>\n<article id=\"entry-enteuthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεῦθεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enteûthen⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">① (Desde Homero; inscrições, papiros, LXX; JosAs 24:5; ParJer 7:32; Justino, D. 6, 1; Taciano 20, 2; <span class=\"greek\">τοὐντεῦθεν</span>, Justino, D. 4:2.) <strong>Indica afastamento de um ponto de origem próximo de quem fala: daqui.</strong> En 22:13; Josefo, Bell. 6, 299; 7, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:9</a>; 13:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:3</a>; 14:31; 1 Cl 53:2 (Êx 32:7). <span class=\"greek\">ἄρατε</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἐ</span>., «tirai estas coisas daqui», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>. <span class=\"greek\">κατάβηθι</span> <span class=\"greek\">ἐ</span>., «desce daqui para casa», GJs 4:2. <span class=\"greek\">ἐντεῦθεν</span> (por <span class=\"greek\">ἔνθεν</span>) <span class=\"greek\">ἐκεῖ</span>, «daqui para lá», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>, variante textual. <span class=\"greek\">ἐντεῦθεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐντεῦθεν</span>, «daqui e dali», isto é, «de ambos os lados» (cf. Nm 22:24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:18</a>. Para esta construção: <span class=\"greek\">ἐντεῦθεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκεῖθεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἐ</span>., «meu reino não é daqui», equivalente a <span class=\"greek\">ἐκ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:36</a>.</p><p class=\"entry-text\">② <strong>Indica a razão ou a fonte de algo: disso; daí.</strong> Cf. Tucídides 1, 5, 1; 1Esd 4:22; Josefo, Ant. 4, 225; C. Ap. 2, 182; Justino, D. 6, 1: <span class=\"greek\">μάθοις</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">ἐντεῦθεν</span>. <span class=\"greek\">ἐ</span>., <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡδονῶν</span>, «disso, isto é, de vossas paixões», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:1</a>. — DELG, s.v. <span class=\"greek\">ἔνθα</span>; M-M.</p></section></article>\n<article id=\"entry-enteuxis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντευξις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énteuxis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Platão e outros; inscrições, papiros [ver especialmente PEnteux]; 2Mc 4:8; TestSol D 2:5.) Em nossa literatura:</p><p class=\"entry-text\">① <strong>Pedido formal dirigido a um alto funcionário ou órgão oficial: petição, requerimento.</strong> Termo técnico administrativo (Políbio 5, 35, 4; Diodoro Sículo 16, 55, 3; Plutarco, Tib. Gracch. 829 [11, 6]; EpArist 252; Josefo, Ant. 15, 79; Justino, A I, 1, 1; inscrições e papiros [Mitteis, Grundzüge, pp. 13ss.; R. Laqueur, Quaestiones epigraph., dissertação, Estrasburgo, 1904, pp. 8ss.; Wilcken, APF 4, 1908, p. 224; OGI 138, n. 10; Dssm., B, pp. 117s.; 143s. (BS, pp. 121; 146); O. Guéraud, Enteux.; Cavassini, Aegyptus 35, 1955, pp. 299ss.; E. Seidl, Ptolem. Rechtsgesch., 1962, p. 65; H. Wolff, D. Justizwesen der Ptolem., 1962, pp. 127ss.]). A carta da igreja de Roma à de Corinto denomina-se petição ou apelo, 1 Cl 63:2; assim também o sermão conhecido como 2 Cl (19:1). Como uma petição designada por <span class=\"greek\">ἔ</span>. é preferencialmente dirigida a um rei, a palavra desenvolve o significado seguinte:</p><p class=\"entry-text\">② <strong>Oração</strong> (Plutarco, Numa 70 [14, 12]: <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ἐντεύξεις</span>; En 99:3; TestSol D 2:5), sobretudo nas seguintes modalidades:</p><p class=\"entry-text\">ⓐ <strong>Oração intercessória</strong> (ao lado de <span class=\"greek\">προσευχή</span>, termo geral para oração, e <span class=\"greek\">εὐχαριστία</span>, oração de ação de graças; ver Elbogen², pp. 4ss.; 73): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a>; cf. Hs 2:5ab; Hs 5, 4, 3.</p><p class=\"entry-text\">ⓑ <strong>Oração em sentido geral:</strong> Hm 5, 1, 6; 10, 3, 2s.; 11:9, 14; Hs 2:5c, 6, 7.</p><p class=\"entry-text\">ⓒ Pode até aproximar-se do sentido de <strong>oração de ação de graças</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:5</a> (= <span class=\"greek\">εὐχαριστία</span> nos versículos 3 e 4).</p><p class=\"entry-text\">ⓓ O contexto exige o sentido de <strong>poder de intercessão</strong>, Hm 10, 3, 3, final; Hs 5, 4, 4. — New Docs 4, p. 104; DELG, s.v. <span class=\"greek\">τυγχάνω</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-entithemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντίθημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entíthēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Aoristo, terceira pessoa do singular: <span class=\"greek\">ἐνέθηκεν</span> (Melitão); particípio <span class=\"greek\">ἐντιθείς</span>, e particípio plural <span class=\"greek\">ἐνθέντες</span>, 2Mc 3:27; particípio perfeito plural <span class=\"greek\">ἐντεθεικότες</span>, 3Mc 5:28; imperativo médio do aoristo, segunda pessoa do plural, <span class=\"greek\">ἔνθεσθε</span>, Pv 8:5. Atestado desde Homero; Luciano, Alex. 47: <span class=\"greek\">ἀλήθειαν</span>; inscrições, papiros, LXX; TestJob 53:7: <span class=\"greek\">ἐνέθεντο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τάφον</span>; TestNapht 2:2; Josefo, Ant. 11, 239; Melitão, P. 20, 138 [B].</p><p class=\"entry-text\"><strong>Pôr dentro; implantar.</strong> «Implantar o nome do Senhor Jesus»: <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰησοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:4</a>, códice D. — DELG, s.v. <span class=\"greek\">τίθημι</span>.</p></section></article>\n<article id=\"entry-entimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντιμος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éntimos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">τιμή</span>; Sófocles e outros; inscrições, papiros, LXX, En, TestJob, AssMos Fgm. k; Josefo, Ant. 15, 243.</p><p class=\"entry-text\">① <strong>Referente a alguém altamente considerado por sua posição ou qualidades pessoais: honrado, respeitado.</strong></p><p class=\"entry-text\">ⓐ Quanto à posição social, <strong>distinto</strong>: <span class=\"greek\">ἐντιμότερός</span> <span class=\"greek\">σου</span>, «alguém mais distinto que tu» (cf. Nm 22:15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:8</a>; o uso de <span class=\"greek\">ἔ</span>. em banquete também aparece em Luciano, Merc. Cond. 26.</p><p class=\"entry-text\">ⓑ Especialmente em razão das qualidades pessoais, <strong>estimado, muito honrado</strong> (oposto a <span class=\"greek\">ἄτιμος</span>): 1 Cl 3:3; <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινά</span>, «ter alguém em estima» (Platão; Diodoro Sículo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:29</a>.</p><p class=\"entry-text\">② <strong>Referente a algo estimado por seu valor considerável: valioso, precioso</strong> (Pseudo-Demóstenes 56, 9; PLond V, 1708, 33 [século VI d.C.]); a respeito de escravos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:2</a>; Hs 5, 2, 2, variante textual. A respeito de pedras (Diodoro Sículo 2, 50, 1; Tb 13:17, manuscritos BA; cf. Jó 28:10): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:4</a>, 6; B 6:2 (em ambos os casos, Is 28:16). — DELG, s.v. <span class=\"greek\">τιμή</span>; M-M.</p></section></article>\n<article id=\"entry-entole-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entolḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐντέλλω</span>; Píndaro, Heródoto e outros; também Melitão, P. 7, 48; 48, 343.</p><p class=\"entry-text\">① <strong>Ordem que autoriza uma ação específica: mandado, ordem escrita, autorização.</strong> Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:57</a> (<span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">ἵνα</span>, como em OGI 441, 59 [81 a.C.]).</p><p class=\"entry-text\">② <strong>Mandato ou determinação: ordem, mandamento.</strong></p><p class=\"entry-text\">ⓐ <strong>Ordens emitidas por pessoas em posições elevadas</strong> (JRS 66, 1976, pp. 106–131, linha 31 [18–19 d.C.], da parte de um legado de Tibério): de um pai (Tb 4:19), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:29</a>; de apóstolos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:10</a>. Instrução de caráter sectário, de tipo judaico (ver <span class=\"greek\">Ἰουδαϊκός</span> e <span class=\"greek\">Ἰουδαῖος</span>, 2), desprovida de sanção divina: <span class=\"greek\">ἐντολαὶ</span> <span class=\"greek\">ἀνθρώπων</span>, «mandamentos humanos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:14</a>. Pápias (2:3) distingue <span class=\"greek\">ἀλλοτρίας</span> <span class=\"greek\">ἐ</span>. da instrução do Senhor.</p><p class=\"entry-text\">ⓑ <strong>Ordens dadas por autoridades divinas</strong> (cf. SIG 888, 51 [238 d.C.] a respeito de decretos imperiais: <span class=\"greek\">ταῖς</span> <span class=\"greek\">θείαις</span> <span class=\"greek\">ἐντολαῖς</span>).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Mandamentos da lei do Antigo Testamento.</strong></p><p class=\"entry-text\">א. O singular abrange todos os mandamentos como a própria lei (4Mc 13:15; 16:24): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐντολήν</span>, «segundo a lei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:56</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:8</a>ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:18</a>; 9:19. <span class=\"greek\">κατὰ</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ἐντολῆς</span> <span class=\"greek\">σαρκίνης</span>, «segundo um sistema jurídico que exige o cumprimento de um requisito físico específico» (isto é, descendência levítica), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:6</a>, variante textual (em lugar de <span class=\"greek\">λόγον</span>). Em contraste com o mandamento de Deus, <span class=\"greek\">ἐ</span>., encontra-se a <span class=\"greek\">παράδοσις</span> dos fariseus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:3</a>; cf. Mc 7:8s.</p><p class=\"entry-text\">ב. Mais frequentemente, o plural representa a totalidade das determinações legais (Epicteto 4, 7, 17: <span class=\"greek\">ἔγνωκα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span>; SEG VIII, 170, 5; Justino, D. 10, 3; Orígenes, C. Cels. 1, 4, 13; Teófilo de Antioquia 3, 11 [p. 226, 28]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>; 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a> (ver também <span class=\"greek\">β</span> abaixo); 18:20.</p><p class=\"entry-text\">ג. A respeito de mandamentos específicos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:36</a>, 38 (cf. EpArist 228: <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πεποίηται</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">μεγίστην</span>; H. Hunt, The Great Commandment, ET 56, 1944, pp. 82s.; C. Burchard, Das doppelte Liebesgebot, em J. Jeremias Festschrift, 1970, pp. 39–62; Justino, D. 40, 1: <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. e outros; <span class=\"greek\">παραβᾶται</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐντολῆς</span>, a respeito de Adão e Eva, Did., Gen. 84, 27); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:5</a>; 12:28, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:2</a>; B 7:3; 9:5. <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντολῶν</span>, «a lei dos mandamentos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:15</a>. A respeito dos levitas: <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">ἀποδεκατοῦν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span>, «possuem o direito legal de recolher dízimos do povo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Mandamentos divinos em geral</strong> (Juliano, Caesares 336c: Mitra transmitiu <span class=\"greek\">ἐντολαί</span> a seus iniciados), no que dizem respeito às pessoas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a> (ver também <span class=\"greek\">α</span>, ב acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:22–24</a>; ISm 8:1. <span class=\"greek\">λαμβάνειν</span>, «receber», 2J 4. <span class=\"greek\">φυλάσσειν</span>, «guardar, observar» (Josefo, Ant. 7, 384), B 4:11. <span class=\"greek\">τηρεῖν</span>, «guardar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:17</a>; 14:12. <span class=\"greek\">ποιεῖν</span>, «cumprir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:2</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">καινήν</span> … <span class=\"greek\">παλαιάν</span>, «mandamento novo … antigo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:7</a>s.; 2J 5. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχομεν</span> … <span class=\"greek\">ἵνα</span>, «temos um mandamento … para que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:21</a>; cf. 2J 5. <span class=\"greek\">κατορθώσασθαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «preservar os mandamentos do Senhor», Hv 3, 5, 3. <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">βαρεῖαι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰσίν</span>, «seus mandamentos não são pesados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:3</a>. <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span>, «andar segundo seus mandamentos», 2J 6.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Ordens de Deus a Cristo:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:18</a> (<span class=\"greek\">λαμβάνειν</span>, «receber», como em Josefo, Bell. 4, 498); 12:49s.; 14:31, variante textual; 15:10b; B 6:1.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <strong>Preceitos de Jesus:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:34</a>; 14:15, 21; 15:10a, 12 (seguido de <span class=\"greek\">ἵνα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:14</a>, variante textual; 2 Cl 3:4; 6:7; 17:3. Aplicado tanto a Deus quanto a Cristo: <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:3</a>s. Acerca dos mandamentos do Sermão do Monte: 1 Cl 13:3. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span> <span class=\"greek\">μου</span>, «cumprir meus mandamentos», 2 Cl 4:5 (de um evangelho desconhecido). <span class=\"greek\">ἐ</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, «mandamento de Jesus Cristo», 2 Cl 17:6 (cf. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span>, Orígenes, C. Cels. 6, 7, 29); IEph 9:2; cf. Pol 2:2; IRo, inscrição inicial. <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «observar os mandamentos do Senhor», 2 Cl 8:4 (cf. Justino, D. 134, 4: <span class=\"greek\">τοὺς</span> <span class=\"greek\">φυλάσσοντας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span>).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. <strong>Ordens do anjo do arrependimento:</strong> Hv 5:5; Hs 10, 3, 4 (texto grego de POxy 404, 17); cf. o título da segunda parte, <span class=\"greek\">ἐντολαί</span>, e ainda Hm 1:2; 2:7 e outros.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. <strong>Expectativa de Deus dirigida aos cristãos, especialmente quanto às suas decisões éticas:</strong> <span class=\"greek\">ἐντολή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀποστόλων</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σωτῆρος</span>, «o mandamento do Senhor e Salvador (dado) por meio de vossos apóstolos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; cf. ITr 13:2. — DELG, s.v. <span class=\"greek\">τέλλω</span>; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-entopios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντόπιος, ία, ιον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entópios⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivado no plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">τόπος</span>; Platão e outros; Dionísio de Halicarnasso 8, 83; inscrições, papiros; o antissemita Molon [século I a.C.], em Eusébio, PE 9, 19, 2.</p><p class=\"entry-text\"><strong>Pertencente a determinado lugar: local.</strong> Substantivado, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐ</span>., «os habitantes do lugar» (OGI 194, 11 [42 a.C.]; PLond II 192, 94, p. 225 [século I d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:12</a> (em contraste com os companheiros de Paulo). — DELG, s.v. <span class=\"greek\">τόπος</span>; M-M.</p></section></article>\n<article id=\"entry-entos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντός</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entós⟧</span><span class=\"separator\">·</span><span>advérbio de lugar; preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de lugar (desde Homero; inscrições, papiros, LXX, JosAs 2:4; EpArist; Fílon; Josefo; Justino, D. 2, 6). Em nossa literatura, funciona somente como <strong>preposição com genitivo</strong>.</p><p class=\"entry-text\">① <strong>Referente a uma área delimitada dentro de algo: dentro de, no interior de, dentro dos limites de.</strong> Luciano, Dial. Mort. 14, 5; JosAs 2:4: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θαλάμου</span>; Josefo, Bell. 3, 175: <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span> <span class=\"greek\">ἐντός</span>; 7, 26; Justino, D. 2, 6: <span class=\"greek\">ὀλίγου</span> … <span class=\"greek\">ἐ</span>. <span class=\"greek\">χρόνου</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυσιαστηρίου</span>, «dentro do santuário», IEph 5:2; ITr 7:2. <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ᾖ</span>, «se alguém estiver em sua companhia» (isto é, na companhia da fé, da esperança e do amor), Pol 3:3.</p><p class=\"entry-text\">Na expressão <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐντὸς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:21</a> (cf. Ox 654, 16 = GTh 3 = JBL 65, 1946, p. 177; ver também W. Schubart, ZNW 20, 1921, pp. 215–223), <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὑμῶν</span> provavelmente se modelou em <span class=\"greek\">ἐν</span> <span class=\"greek\">σοί</span> (= «[Deus] está entre vós»), Is 45:14. Lucas, porém, prefere <span class=\"greek\">ἐντός</span> no sentido de <strong>«entre vós, em vosso meio»</strong>, seja no presente, seja subitamente num futuro próximo. Cf. Xenofonte, Hell. 2, 3, 19: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τούτων</span>; An. 1, 10, 3: <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτῶν</span> (quanto à relevância da segunda passagem de Xenofonte, ver Field, Notes, p. 71, e Roberts, adiante); POxy 2342, 8 [102 d.C.], a respeito de uma mulher que mantém reserva de vinho <span class=\"greek\">ἐντὸ</span> <span class=\"greek\">αὑτῆ</span>, «sob seu próprio controle»; Sl 87:6, Símaco; cf. Josefo, Ant. 6, 315; Arriano, Anab. 5, 22, 4: <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτῶν</span> = «em seu meio». Assim também o texto da NRSV; ver Noack e Bretscher adiante.</p><p class=\"entry-text\">A interpretação <strong>«dentro de vós, em vossos corações»</strong> possui fundamento linguístico em Sl 38:4; 102:1; 108:22 (todos com <span class=\"greek\">ἐντός</span> <span class=\"greek\">μου</span>), ver ainda Josefo, Ant. 5, 107; entretanto, Lucas geralmente evita referir-se ao reinado de Deus como realidade psicológica. A passagem suscitou amplo debate: A. Wabnitz, RTQR 18, 1909, pp. 221ss., 289ss., 456ss.; C. Bruston, ibid., pp. 346ss.; B. Easton, AJT 16, 1912, pp. 275–283; K. Proost, TT 48, 1914, pp. 246ss.; J. Héring, Le royaume de Dieu et sa venue, 1937; P. Allen, ET 50, 1939, pp. 233–235; A. Sledd, ibid., pp. 235–237; W. Kümmel, Verheissung u. Erfüllung, 1945, pp. 17ss.; B. Noack, D. Gottesreich bei Lk (17:20–24), 1948; C. Roberts, HTR 41, 1948, pp. 1–8, citando PRossGeorg III, 1, 9: <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐντός</span> <span class=\"greek\">μου</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">εὕρω</span>; H. Cadbury, Christian Century 67, 1950, pp. 172s. («dentro de vossa posse ou alcance»; cf. Tertuliano, Adv. Marc. 4, 35); cf. Pol 3:3 acima e J. Griffiths, ET 63, 1951/52, pp. 30s.; H. Riesenfeld, Nuntius 2, 1949, pp. 11s.; A. Wikgren, ibid. 4, 1950, pp. 27s.; P. Bretscher, CTM 15, 1944, pp. 730–766; 22, 1951, pp. 895–907. Com ênfase nas implicações morais: R. Frick, Beih. ZNW 6, 1928, pp. 6–8; ver A. Rüstow, ZNW 51, 1960, pp. 197–224; J. Zmijewski, D. Eschatologiereden d. LkEv, 1972, pp. 361–397.</p><p class=\"entry-text\">② <strong>Referente àquilo que está dentro de um recipiente ou espaço: conteúdo, parte interior.</strong> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποτηρίου</span>, «o interior do copo», isto é, «o que está no copo» (cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span>, 1Mc 4:48; também escólio a Nicandro, Alexiph. 479: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐντός</span>, «a parte interior»; Is 16:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:26</a>. — DELG, s.v. <span class=\"greek\">ἐν</span>; M-M.</p></section></article>\n<article id=\"entry-entrepo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entrépō⟧</span><span class=\"separator\">·</span><span>verbo; usos ativos e passivos</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Passivo: segundo futuro <span class=\"greek\">ἐντραπήσομαι</span>; segundo aoristo <span class=\"greek\">ἐνετράπην</span>; perfeito <span class=\"greek\">ἐντέτραμμαι</span>, 1Esd 8:71. Ver <span class=\"greek\">τρέπω</span>; Homero e outros; papiros, LXX, Josefo. Sentido primário: «fazer voltar-se»; em nossa literatura, usos metafóricos.</p><p class=\"entry-text\">① <strong>Fazer que alguém se volte em razão da vergonha: envergonhar.</strong> Com acusativo <span class=\"greek\">τινά</span> (Diógenes Laércio 2, 29; Eliano, VH 3, 17; Sexto Empírico, Psych. 3, 16): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐντρέπων</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">γράφω</span> <span class=\"greek\">ταῦτα</span>, «não escrevo estas coisas para vos envergonhar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:14</a>. No passivo, <strong>ser envergonhado, ficar envergonhado</strong> (UPZ 62, 29 [161/160 a.C.]; 70, 4; Sl 34:26; Is 44:11): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:8</a>; IMg 12.</p><p class=\"entry-text\">② <strong>Mostrar deferência a alguém, reconhecendo-lhe posição especial: voltar-se para algo/alguém, ter consideração por, respeitar.</strong> Com acusativo <span class=\"greek\">τινά</span>: 1 Cl 38:2, variante textual. No passivo, com sentido médio (Álexis, comediógrafo, 71, ed. Kock II, p. 320; Políbio 9, 36, 10; 30, 9, 2; Diodoro Sículo 19, 7, 4: <span class=\"greek\">θεούς</span>; Êx 10:3; Sb 2:10; 6:7; Josefo, Bell. 7, 362): <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span> <span class=\"greek\">μου</span>, «meu filho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:13</a>. <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐντρεπόμενος</span>, «que não demonstrava deferência a ser humano algum» (em paralelo à atitude do juiz perante Deus; v. 3a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:2</a>; cf. v. 4 (cf. Platão, Leg. 11, 917b). <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀδελφήν</span>, «respeitar alguém como irmã», Hv 1, 1, 7. <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰησοῦν</span>, «o Senhor Jesus», 1 Cl 21:6. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἰσχυρόν</span>, «o poderoso», 1 Cl 38:2 (ver também a variante textual acima). <span class=\"greek\">ἀλλήλους</span>, «uns aos outros», IMg 6:2. <span class=\"greek\">τοὺς</span> <span class=\"greek\">διακόνους</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">Ἰησοῦν</span>, «os diáconos como Jesus», ITr 3:1; cf. ISm 8:1; ITr 3:2. Com <span class=\"greek\">αὐτούς</span> a subentender do contexto: <span class=\"greek\">ἐντρεπόμεθα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>. — DELG, s.v. <span class=\"greek\">τρέπω</span>; M-M.</p></section></article>\n<article id=\"entry-entrepho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦entréphō⟧</span><span class=\"separator\">·</span><span>verbo; particípio médio-passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">τρέφω</span>; Eurípides e outros; voz média atestada desde Hesíodo, Op. 781. O sentido primário é «criar, educar»; posteriormente, <strong>formar ou instruir em algo</strong>, com dativo <span class=\"greek\">τινί</span> (Platão, Leg. 7, 798a; Epicteto 4, 4, 48; Fílon, Spec. Leg. 1, 314; Leg. ad Gai. 195: <span class=\"greek\">τ</span>. <span class=\"greek\">ἱεροῖς</span> <span class=\"greek\">γράμμασιν</span>; Josefo, Bell. 6, 102; C. Ap. 1, 269).</p><p class=\"entry-text\"><span class=\"greek\">ἐντρεφόμενος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, «sendo nutrido pelas palavras da fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6</a> (Ath. 11, 1: <span class=\"greek\">οἱ</span> <span class=\"greek\">λογοι</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">ἐντρεφόμεθα</span>; quanto à imagem, ver Straub, p. 24). — DELG, s.v. <span class=\"greek\">τρέφω</span>; M-M.</p></section></article>\n<article id=\"entry-entromos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντρομος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éntromos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Plutarco, Fab. Max. 175 [3, 1]; Meleagro [século I a.C.], Anth. Pal. 5, 204, 8; escólio a Eurípides, Phoen. 1284–87; LXX; JosAs, cap. 18, códice A [p. 68, 17 Bat.]; Justino, D. 103, 8.</p><p class=\"entry-text\"><strong>Referente ao estado de quem treme em razão da exposição a circunstâncias avassaladoras ou ameaçadoras: trêmulo, tremendo.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:47</a>, códice D. <span class=\"greek\">ἔ</span>. <span class=\"greek\">γενόμενος</span>, «tendo-se posto a tremer» (cf. Sorano, pp. 68, 7s.; Sl 17:8; 76:19); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:32</a>; 16:29; GJs 11:1. <span class=\"greek\">ἔκφοβος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔ</span>., «cheio de temor e tremor» (como em 1Mc 13:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:21</a>. — DELG, s.v. <span class=\"greek\">τρέμω</span>; M-M.</p></section></article>"};
